  "え？先生に？うーん、ちょっと仕事が……。": "/assets/audio/a_cf6dec486c6b6e9c.m4a",
  "ええ、15,000円払わないといけません。": "/assets/audio/a_f9d8da6602a7bd8e.m4a",
  "ええ、いいですよ。": "/assets/audio/a_f5d325909e4d81b7.m4a",
  "ええ、お願いします。": "/assets/audio/a_91e015a78ca0f76b.m4a",
  "ええ、ぜひ。皆さん、ほんとうにいろいろお世話になりました。": "/assets/audio/a_bc8de158556b2109.m4a",
  "ええ、そうですね。": "/assets/audio/a_77f3b4a384a52b22.m4a",
  "ええ、ちょっと郵便局まで。": "/assets/audio/a_a598ce92c1f91499.m4a",
  "ええ、ほかにもいろいろありますよ。懐中電灯とか、ラジオとか……。": "/assets/audio/a_9b5676fb5aff0808.m4a",
  "ええ、元気です。あのう、木村さん、クラシックのコンサート、いっしょにいかがですか。": "/assets/audio/a_2eb11f978c26d2d9.m4a",
  "ええ、今の仕事が終わったら、休みを取ろうと思っています。": "/assets/audio/a_f912eb143781780e.m4a",
  "ええ、残念ですが、友達と約束がありますから、……。": "/assets/audio/a_d4e0f595f1391a51.m4a",
  "ええ。": "/assets/audio/a_88149875daa0d123.m4a",
  "ええ。それで今友達と英語を勉強しているんですが……。": "/assets/audio/a_da9bd311b40e6b4f.m4a",
  "ええ。ちょっと太ってしまったんです。": "/assets/audio/a_520f04bc0128520e.m4a",
  "ええ。でも、月に2、3回週末に帰るつもりです。": "/assets/audio/a_b4bae2475d90ce5f.m4a",
  "ええ。でも、友達ができるかどうか、少し心配です。": "/assets/audio/a_29152246054ea947.m4a",
  "ええ。また今度お願いします。": "/assets/audio/a_3832a6a0a3037eaa.m4a",
  "ええ。会社の人にもらいました。メキシコのお土産です。": "/assets/audio/a_0b0517b223fa35f3.m4a",
  "ええ。甘いお菓子を食べたあとで、お茶を飲むと、おいしいんですよ。": "/assets/audio/a_de11045613049058.m4a",
  "ええ。降りると、前に公園があります。図書館は公園の中の白い建物です。": "/assets/audio/a_7430a5f0760542cb.m4a",
  "ええ。今から行きましょうか。": "/assets/audio/a_93d96f322610c576.m4a",
  "ええ。残業が多いんです。": "/assets/audio/a_027fa8b99ffab415.m4a",
  "ええ。次の試合もきっと勝つと思います。": "/assets/audio/a_26c0d16c73e4018b.m4a",
  "ええ。趣味は自分で家具を作ることなんです。": "/assets/audio/a_eefe28cb6ce9d034.m4a",
  "ええ。息子は来年大学の入学試験があるから、東京に残ると言うし、妻も今の会社をやめたくないと言うんです。": "/assets/audio/a_b6929dab707e3549.m4a",
  "ええ。天気がいい日には海が見えるんです。": "/assets/audio/a_ac2ce20056cf81b9.m4a",
  "ええ。日本は強かったですね。": "/assets/audio/a_ef7ca19379cc79b2.m4a",
  "ええ。物を片づけるのが好きなんです。": "/assets/audio/a_2fae233f2cdc08c5.m4a",
  "ええ。北海道へ馬の写真を撮りに行きたいです。": "/assets/audio/a_4eb270676a2dbd42.m4a",
  "えーと": "/assets/audio/a_9ccfa57d008e7faf.m4a",
  "えーと、駅から遠くない所がいいです。": "/assets/audio/a_1fc8fa790eee1cce.m4a",
  "えーと、確か、本と傘が入っています。": "/assets/audio/a_ab158b40fa561e39.m4a",
  "えーと……。": "/assets/audio/a_650f2eed0dfc587d.m4a",
