  "えっ、ほんとうですか。": "/assets/audio/a_7eb24967c2ce6b7a.m4a",
  "えっ、先にお菓子を食べるんですか。": "/assets/audio/a_12d178fdbb384198.m4a",
  "えっ？": "/assets/audio/a_5b8d7982954d221e.m4a",
